// src/logger.ts
// 日志输出与级别过滤

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

export const LOG_LEVELS: readonly LogLevel[] = ['debug', 'info', 'warn', 'error'];

const LEVEL_ORDER: Record<LogLevel, number> = {
  debug: 0,
  info: 1,
  warn: 2,
  error: 3,
};

export const DEFAULT_LOG_LEVEL: LogLevel = 'info';

export function isLogLevel(value: unknown): value is LogLevel {
  return typeof value === 'string' && (LOG_LEVELS as readonly string[]).includes(value);
}

export function format(level: LogLevel, message: string): string {
  return `[${level}] ${message}`;
}

export interface Logger {
  readonly level: LogLevel;
  /** 输出一条日志；若低于配置的 logLevel 则返回 null（不发出）。 */
  log(level: LogLevel, message: string): string | null;
  debug(message: string): string | null;
  info(message: string): string | null;
  warn(message: string): string | null;
  error(message: string): string | null;
}

/**
 * 创建一个按给定 logLevel 过滤输出的 logger。
 * 仅输出级别 >= 配置级别（debug < info < warn < error）的日志。
 */
export function createLogger(level: LogLevel = DEFAULT_LOG_LEVEL): Logger {
  if (!isLogLevel(level)) {
    throw new Error(`invalid logLevel: ${String(level)}`);
  }
  const threshold = LEVEL_ORDER[level];
  const emit = (lvl: LogLevel, message: string): string | null =>
    LEVEL_ORDER[lvl] >= threshold ? format(lvl, message) : null;
  return {
    level,
    log: emit,
    debug: (message) => emit('debug', message),
    info: (message) => emit('info', message),
    warn: (message) => emit('warn', message),
    error: (message) => emit('error', message),
  };
}

// 低层格式化函数，始终输出（不做级别过滤）
export function log(level: LogLevel, message: string): string {
  return format(level, message);
}

