// 配置 schema 与解析
import {
  type LogLevel,
  LOG_LEVELS,
  DEFAULT_LOG_LEVEL,
  isLogLevel,
} from './logger.js';

export interface AppConfig {
  name: string;
  logLevel: LogLevel;
}

export function parseConfig(raw: Record<string, unknown>): AppConfig {
  if (typeof raw.name !== 'string' || raw.name.length === 0) {
    throw new Error('name is required');
  }
  const logLevel = raw.logLevel === undefined ? DEFAULT_LOG_LEVEL : raw.logLevel;
  if (!isLogLevel(logLevel)) {
    throw new Error(
      `invalid logLevel: ${String(raw.logLevel)} (expected one of: ${LOG_LEVELS.join(', ')})`
    );
  }
  return { name: raw.name, logLevel };
}

import { describe, it, expect } from 'vitest';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { parseConfig } from '../src/config-schema.js';
import { loadConfig } from '../src/loader.js';
import { createLogger, log } from '../src/logger.js';

describe('config 基础', () => {
  it('name 解析', () => {
    expect(parseConfig({ name: 'svc' }).name).toBe('svc');
  });
  it('name 缺失抛错', () => {
    expect(() => parseConfig({})).toThrow('name');
  });
});

describe('config logLevel', () => {
  it('默认 logLevel 为 info', () => {
    expect(parseConfig({ name: 'svc' }).logLevel).toBe('info');
  });
  it('解析合法 logLevel', () => {
    expect(parseConfig({ name: 'svc', logLevel: 'debug' }).logLevel).toBe('debug');
    expect(parseConfig({ name: 'svc', logLevel: 'info' }).logLevel).toBe('info');
    expect(parseConfig({ name: 'svc', logLevel: 'warn' }).logLevel).toBe('warn');
    expect(parseConfig({ name: 'svc', logLevel: 'error' }).logLevel).toBe('error');
  });
  it('非法 logLevel 抛错', () => {
    expect(() => parseConfig({ name: 'svc', logLevel: 'verbose' })).toThrow('logLevel');
    expect(() => parseConfig({ name: 'svc', logLevel: 123 })).toThrow('logLevel');
    expect(() => parseConfig({ name: 'svc', logLevel: null })).toThrow('logLevel');
    expect(() => parseConfig({ name: 'svc', logLevel: '' })).toThrow('logLevel');
  });
});

describe('loader 集成', () => {
  it('loadConfig 默认与合法 logLevel', () => {
    const dir = mkdtempSync(join(tmpdir(), 'cfg-'));
    try {
      const defaultFile = join(dir, 'default.json');
      writeFileSync(defaultFile, JSON.stringify({ name: 'svc' }));
      expect(loadConfig(defaultFile).logLevel).toBe('info');

      const good = join(dir, 'good.json');
      writeFileSync(good, JSON.stringify({ name: 'svc', logLevel: 'debug' }));
      expect(loadConfig(good).logLevel).toBe('debug');
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
  it('loadConfig 拒绝非法 logLevel', () => {
    const dir = mkdtempSync(join(tmpdir(), 'cfg-'));
    try {
      const bad = join(dir, 'bad.json');
      writeFileSync(bad, JSON.stringify({ name: 'svc', logLevel: 'verbose' }));
      expect(() => loadConfig(bad)).toThrow('logLevel');
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});

describe('logger 级别过滤', () => {
  it('默认 createLogger 过滤低于 info 的级别', () => {
    const logger = createLogger();
    expect(logger.debug('d')).toBeNull();
    expect(logger.info('i')).toBe('[info] i');
    expect(logger.warn('w')).toBe('[warn] w');
    expect(logger.error('e')).toBe('[error] e');
  });
  it('log 方法遵循配置的 logLevel', () => {
    const logger = createLogger('warn');
    expect(logger.log('debug', 'd')).toBeNull();
    expect(logger.log('info', 'i')).toBeNull();
    expect(logger.log('warn', 'w')).toBe('[warn] w');
    expect(logger.log('error', 'e')).toBe('[error] e');
  });
  it('debug 级别输出全部级别', () => {
    const logger = createLogger('debug');
    expect(logger.debug('d')).toBe('[debug] d');
    expect(logger.info('i')).toBe('[info] i');
    expect(logger.warn('w')).toBe('[warn] w');
    expect(logger.error('e')).toBe('[error] e');
  });
  it('error 级别只输出 error', () => {
    const logger = createLogger('error');
    expect(logger.debug('d')).toBeNull();
    expect(logger.info('i')).toBeNull();
    expect(logger.warn('w')).toBeNull();
    expect(logger.error('e')).toBe('[error] e');
  });
  it('log 输出带级别前缀', () => {
    expect(log('info', 'hi')).toBe('[info] hi');
  });
});

